import java.util.*;
import java.io.*;

public class Main {
    static String[] sortWords(String[] alphabet, String[] words) {
        // alphabet lists the letters in dictionary order; a letter may be several characters long
        // Write your solution here
        return words;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int m = Integer.parseInt(st.nextToken());
        String[] alphabet = new String[m];
        for (int i = 0; i < m; i++) alphabet[i] = st.nextToken();
        int n = Integer.parseInt(st.nextToken());
        String[] words = new String[n];
        for (int i = 0; i < n; i++) words[i] = st.nextToken();
        System.out.println(String.join(" ", sortWords(alphabet, words)));
    }
}
